import "axe-core";
export function createAxeRunner(config, onScanStateChange) {
  let isScanRunning = false;
  const axe = window.axe;
  axe.configure(config.options);
  async function run() {
    if (isScanRunning) {
      return [];
    }
    isScanRunning = true;
    onScanStateChange(true);
    const startTime = Date.now();
    const MIN_SCAN_DURATION = 500;
    try {
      const result = await new Promise((resolve, reject) => {
        axe.run({
          // Exclude any Nuxt DevTools Elements and highlight wrappers
          exclude: [
            '[id^="nuxt-devtools-"]',
            "#__nuxt_a11y_badge_container__"
          ]
        }, {
          elementRef: true,
          ...config.runOptions
        }, (error, results) => {
          if (error)
            reject(error);
          else resolve(results);
        });
      });
      const elapsed = Date.now() - startTime;
      if (elapsed < MIN_SCAN_DURATION) {
        await new Promise((resolve) => setTimeout(resolve, MIN_SCAN_DURATION - elapsed));
      }
      return result.violations;
    } catch (error) {
      console.error("Axe scan failed:", error);
      return [];
    } finally {
      isScanRunning = false;
      onScanStateChange(false);
    }
  }
  return {
    run
  };
}
